{
  "findings": [
    {
      "check_id": "CKV_AWS_126",
      "title": "EC2 detailed monitoring is disabled",
      "resource": "aws_instance.ubuntu[2]",
      "severity": "MEDIUM",
      "explanation": "Detailed monitoring is not enabled, reducing the granularity of operational metrics available for detecting anomalous behavior and investigating incidents."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "EC2 permits Instance Metadata Service v1",
      "resource": "aws_instance.ubuntu[2]",
      "severity": "MEDIUM",
      "explanation": "No metadata options require IMDSv2, so the instance may accept unauthenticated IMDSv1 requests and be more exposed to credential theft through SSRF."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "EC2 root volume encryption is not enforced",
      "resource": "aws_instance.ubuntu[2]",
      "severity": "MEDIUM",
      "explanation": "The instance does not explicitly encrypt its root EBS volume, so data at rest is not guaranteed to be encrypted independently of account-level defaults."
    },
    {
      "check_id": "CKV_AWS_88",
      "title": "EC2 instance is assigned a public IP address",
      "resource": "aws_instance.ubuntu[1]",
      "severity": "MEDIUM",
      "explanation": "The count-index condition explicitly assigns a public IP to the second instance, unnecessarily increasing its exposure to internet-originated traffic."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"ubuntu\" {\n  count         = 3\n  ami           = data.aws_ami.ubuntu_14_04.image_id\n  instance_type = \"t2.micro\"\n\n  associate_public_ip_address = false\n  subnet_id                   = aws_subnet.my_subnet.id\n  monitoring                  = true\n\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n\n  root_block_device {\n    encrypted = true\n  }\n}\n",
  "fix_summary": "Disabled public IP assignment, enabled detailed monitoring, required IMDSv2, and enforced encryption for root EBS volumes. EBS optimization was not enabled because t2.micro does not support configurable EBS optimization, and no IAM role was added because this file defines no workload requiring AWS API permissions."
}
